package com.devtunasoft.tuneros.qa20

import com.devtunasoft.tuneros.core.ParentalAttemptLimit
import com.devtunasoft.tuneros.core.ParentalPolicy
import java.io.File
import java.nio.ByteBuffer
import java.nio.charset.CodingErrorAction
import java.nio.charset.StandardCharsets
import java.security.MessageDigest
import kotlin.system.exitProcess

/**
 * QA-20 shared, framework-free host gate for the bounded runtime parental decision slice.
 *
 * The real pure-Kotlin ParentalControls source is compiled with this object. The fixture is
 * regenerated byte-for-byte from fixed constants, parsed strictly and replayed through the
 * product classes. Every token is invented scratch data; the leak marker is derived at run
 * time and is never stored in source, fixture or diagnostics.
 */
object Qa20Contract {
    const val SEED = 20261123L
    const val MAX_FAILURES = 5
    const val LOCK_MILLIS = 60_000L
    const val STEP_MILLIS = 100L
    const val MAX_GROUPS = 100
    const val EVENT_FAMILIES = 8
    const val EVENTS_PER_FAMILY = 20
    const val EVENT_COUNT = EVENT_FAMILIES * EVENTS_PER_FAMILY
    const val POLICY_FAMILIES = 4
    const val POLICY_PER_FAMILY = 20
    const val POLICY_COUNT = POLICY_FAMILIES * POLICY_PER_FAMILY
    const val CORRUPT_COUNT = 8
    const val MAX_LINE = 256
    const val MAX_HEX = 1024
    const val MAX_FIXTURE_BYTES = 262_144L
    const val HEAP_LIMIT_BYTES = 48L * 1024 * 1024
    const val CYCLES = 6
    const val SECRET_LENGTH = 12

    const val DATA_FILES = "contract.txt,dimensions.tsv,events.tsv,policy.tsv,corrupt.hex"
    const val ALL_FILES = "$DATA_FILES,sha256.txt"

    // Pinned after the first deterministic generation; verify recomputes and compares.
    const val PINNED_EVENTS_SHA = "8c2c8cdec14e90ccc5bf2054e20626ae51c26ef578c7389555bfa389de21578d"
    const val PINNED_POLICY_SHA = "9403de81e5688cd5f961a7313276b8dfa3acb281dbec3b90bd293a903d2a117b"
    const val PINNED_CORRUPT_SHA = "cfd50e7debea1c2f8825cd867ec30bd196658b30947abd88a2ecd222caa30e63"
    const val PINNED_EVENTS_DIGEST = "96558c99df745559"
    const val PINNED_POLICY_DIGEST = "e5a9f72a0b9ad040"

    const val EVENT_HEADER = "qa20v1"
    const val POLICY_HEADER = "qa20p1"
    const val CORRUPT_HEADER = "qa20x1"
    const val BASE_NOW = 1_700_000_000_000L

    val EVENT_FAMILY_NAMES = listOf(
        "REJECT_STREAK", "LOCK_ON_FIFTH", "LOCKED_REFUSES", "LOCK_EXPIRY",
        "CORRECT_CLEARS", "MIXED_LIMIT", "RESTART_FAILURES", "RESTART_LOCK",
    )
    val POLICY_FAMILY_NAMES = listOf("GROUP", "CHANNEL", "RECORDING", "BOUNDED_SET")
    val CORRUPT_REASONS = listOf(
        "HEADER_STRICT", "FIELD_COUNT", "INT_BOUNDS", "FAMILY_CODE",
        "LINE_BOUNDS", "NON_ASCII", "ENTRY_CODE", "EXPECTED_CODE",
    )

    private val ID_REGEX = Regex("qa20e-[0-9]{5}")
    private val POLICY_ID_REGEX = Regex("qa20p-[0-9]{5}")
    private val CORRUPT_ID_REGEX = Regex("qa20x-[0-9]{2}")
    private val HEX_REGEX = Regex("[0-9a-f]{2,}")
    private val SHA_REGEX = Regex("[0-9a-f]{64}")
    private val OUTCOME_ONE = Regex("(A|R[1-4]|L[0-9]{10,16})")
    private val OUTCOME_REGEX = Regex("$OUTCOME_ONE(,$OUTCOME_ONE)*")
    private val HEX_DIGITS = "0123456789abcdef"

    private val SENSITIVE_PATTERNS = listOf(
        "://", "http", "m3u8", "xmltv", "pin=", "pin:", "passwd", "password",
        "credential", "bearer ", "authorization:", "private key", "api_key",
        "apikey", "secret=", "token=", "rec000", "rec001",
    )

    data class Event(
        val id: String,
        val family: String,
        val failures: Int,
        val lockUntil: Long,
        val now: Long,
        val entries: String,
        val expected: String,
    ) {
        fun render(): String = listOf(
            EVENT_HEADER, id, family, failures.toString(), lockUntil.toString(),
            now.toString(), entries, expected,
        ).joinToString("\t")
    }

    data class Policy(
        val id: String,
        val family: String,
        val group: String,
        val channel: String,
        val groupKnown: Boolean,
        val restrictedGroup: String,
        val restrictedChannel: String,
        val unlocked: Boolean,
        val setSize: Int,
        val op: String,
        val expected: String,
    ) {
        fun render(): String = listOf(
            POLICY_HEADER, id, family, group, channel,
            if (groupKnown) "TRUE" else "FALSE", restrictedGroup, restrictedChannel,
            if (unlocked) "TRUE" else "FALSE", setSize.toString(), op, expected,
        ).joinToString("\t")
    }

    data class Corrupt(val name: String, val hex: String, val reason: String) {
        fun render(): String = listOf(CORRUPT_HEADER, name, hex, reason).joinToString("\t")
    }

    class ParseFail(val code: String) : Exception(code)

    fun interface Sink {
        fun line(value: String)
    }

    data class Result(val checks: Int, val passed: Int, val failed: Int, val first: String?) {
        val ok: Boolean get() = failed == 0
    }

    // ------------------------------------------------------------------- primitives

    fun deriveSecret(): String {
        val digest = MessageDigest.getInstance("SHA-256")
            .digest("qa20-runtime-marker-20261123".toByteArray(StandardCharsets.UTF_8))
        return hex(digest).take(SECRET_LENGTH)
    }

    private fun hex(bytes: ByteArray): String = buildString(bytes.size * 2) {
        for (b in bytes) {
            val v = b.toInt() and 0xFF
            append(HEX_DIGITS[v shr 4])
            append(HEX_DIGITS[v and 0x0F])
        }
    }

    private fun unhex(value: String): ByteArray? {
        if (value.length % 2 != 0 || value.length > MAX_HEX) return null
        val out = ByteArray(value.length / 2)
        for (i in out.indices) {
            val hi = HEX_DIGITS.indexOf(value[i * 2])
            val lo = HEX_DIGITS.indexOf(value[i * 2 + 1])
            if (hi < 0 || lo < 0) return null
            out[i] = ((hi shl 4) or lo).toByte()
        }
        return out
    }

    fun sha256(bytes: ByteArray): String = hex(MessageDigest.getInstance("SHA-256").digest(bytes))

    private fun fnv(bytes: ByteArray): String {
        var h = -3750763034362895579L
        for (b in bytes) {
            h = h xor (b.toLong() and 0xFFL)
            h *= 1099511628211L
        }
        return java.lang.Long.toHexString(h).padStart(16, '0')
    }

    private fun utf8(value: String): ByteArray = value.toByteArray(StandardCharsets.UTF_8)

    private fun strictUtf8(bytes: ByteArray, code: String): String = try {
        StandardCharsets.UTF_8.newDecoder()
            .onMalformedInput(CodingErrorAction.REPORT)
            .onUnmappableCharacter(CodingErrorAction.REPORT)
            .decode(ByteBuffer.wrap(bytes)).toString()
    } catch (e: Exception) {
        throw ParseFail(code)
    }

    private fun normalizeToken(value: String): String = value.trim().lowercase(java.util.Locale.ROOT)

    // -------------------------------------------------------------- independent oracle

    private fun oracleEvent(e: Event): String {
        var failures = e.failures
        var lock = e.lockUntil
        val out = ArrayList<String>()
        for ((index, entry) in e.entries.withIndex()) {
            val at = e.now + index * STEP_MILLIS
            if (at < lock) {
                out.add("L$lock")
            } else if (entry == 'C') {
                failures = 0
                out.add("A")
            } else {
                failures++
                if (failures >= MAX_FAILURES) {
                    failures = 0
                    lock = at + LOCK_MILLIS
                    out.add("L$lock")
                } else {
                    out.add("R${MAX_FAILURES - failures}")
                }
            }
        }
        return out.joinToString(",")
    }

    private fun oraclePolicy(p: Policy): String {
        if (p.family == "BOUNDED_SET") {
            val names = setName(p.setSize, p.id)
            val unique = names.toSet()
            return if (p.op == "NORMALIZE") {
                if (unique.isEmpty() || unique.size > MAX_GROUPS) "REJECT" else "TRUE"
            } else {
                val current = names.dropLast(1).toSet() + names.last()
                if (current.size > MAX_GROUPS) "REJECT" else "TRUE"
            }
        }
        if (p.unlocked) return "FALSE"
        return when (p.family) {
            "GROUP" -> {
                if (p.group == "NONE") "FALSE"
                else if (normalizeToken(p.group) == normalizeToken(p.restrictedGroup)) "TRUE" else "FALSE"
            }
            "CHANNEL" -> {
                val g = if (p.group == "NONE") null else normalizeToken(p.group)
                val restrictedG = if (p.restrictedGroup == "NONE") emptySet() else setOf(normalizeToken(p.restrictedGroup))
                if (g != null && g in restrictedG) "TRUE"
                else if (p.restrictedChannel != "NONE" &&
                    normalizeToken(p.channel) == normalizeToken(p.restrictedChannel)) "TRUE"
                else "FALSE"
            }
            "RECORDING" -> {
                if (!p.groupKnown) if (p.restrictedGroup != "NONE") "TRUE" else "FALSE"
                else if (p.group != "NONE" && p.restrictedGroup != "NONE" &&
                    normalizeToken(p.group) == normalizeToken(p.restrictedGroup)) "TRUE"
                else "FALSE"
            }
            else -> "UNKNOWN_FAMILY"
        }
    }

    // --------------------------------------------------------------- product replay

    private fun productEvent(e: Event): String {
        val gate = ParentalAttemptLimit(
            maxFailures = MAX_FAILURES,
            lockMillis = LOCK_MILLIS,
            failures = e.failures,
            lockedUntilMillis = e.lockUntil,
        )
        val out = ArrayList<String>()
        for ((index, entry) in e.entries.withIndex()) {
            val outcome = gate.attempt(entry == 'C', e.now + index * STEP_MILLIS)
            out.add(
                when (outcome) {
                    is ParentalAttemptLimit.Outcome.Accepted -> "A"
                    is ParentalAttemptLimit.Outcome.Rejected -> "R${outcome.attemptsLeft}"
                    is ParentalAttemptLimit.Outcome.Locked -> "L${outcome.untilMillis}"
                }
            )
        }
        return out.joinToString(",")
    }

    private fun setName(size: Int, id: String): List<String> {
        val seq = id.substringAfterLast('-').toIntOrNull() ?: 0
        val duplicated = seq % 4 == 2 && size > 1
        return (0 until size).map { n ->
            val key = if (duplicated && n == size - 1) size - 2 else n
            "qa20grp-${key.toString().padStart(3, '0')}"
        }
    }

    private fun productPolicy(p: Policy): String = try {
        val groups = if (p.restrictedGroup == "NONE") emptySet() else setOf(p.restrictedGroup)
        val channels = if (p.restrictedChannel == "NONE") emptySet() else setOf(p.restrictedChannel)
        val group = if (p.group == "NONE") null else p.group
        val decision = when (p.family) {
            "GROUP" -> ParentalPolicy.requiresPin(group, groups, p.unlocked)
            "CHANNEL" -> ParentalPolicy.requiresPinForChannel(p.channel, group, groups, channels, p.unlocked)
            "RECORDING" -> ParentalPolicy.requiresPinForRecording(group, p.groupKnown, groups, p.unlocked)
            "BOUNDED_SET" -> {
                val names = setName(p.setSize, p.id)
                if (p.op == "NORMALIZE") ParentalPolicy.normalizeAll(names.toSet())
                else ParentalPolicy.restrict(names.dropLast(1).toSet(), names.last(), true)
                true
            }
            else -> false
        }
        if (decision) "TRUE" else "FALSE"
    } catch (e: IllegalArgumentException) {
        "REJECT"
    }

    // ------------------------------------------------------------------- generation

    private fun buildEvents(): List<Event> {
        val out = ArrayList<Event>(EVENT_COUNT)
        for (f in EVENT_FAMILY_NAMES.indices) {
            val family = EVENT_FAMILY_NAMES[f]
            for (i in 0 until EVENTS_PER_FAMILY) {
                val now = BASE_NOW + f * 1_000_000L + i * 1_000L
                val failures: Int
                val lock: Long
                val entries: String
                when (family) {
                    "REJECT_STREAK" -> { failures = i % 4; lock = 0L; entries = "W" }
                    "LOCK_ON_FIFTH" -> { failures = 4; lock = 0L; entries = "W" }
                    "LOCKED_REFUSES" -> { failures = 0; lock = now + 1_000L; entries = if (i % 2 == 0) "C" else "W" }
                    "LOCK_EXPIRY" -> { failures = 0; lock = now; entries = if (i % 2 == 0) "C" else "W" }
                    "CORRECT_CLEARS" -> { failures = i % 4; lock = 0L; entries = "WCC" }
                    "MIXED_LIMIT" -> { failures = 0; lock = 0L; entries = "WWWWCW" }
                    "RESTART_FAILURES" -> { failures = i % 4; lock = 0L; entries = "CW" }
                    else -> { failures = 0; lock = now + LOCK_MILLIS; entries = "CW" }
                }
                val id = "qa20e-" + (f * EVENTS_PER_FAMILY + i).toString().padStart(5, '0')
                val e = Event(id, family, failures, lock, now, entries, "")
                out.add(e.copy(expected = oracleEvent(e)))
            }
        }
        return out
    }

    private fun buildPolicy(): List<Policy> {
        val out = ArrayList<Policy>(POLICY_COUNT)
        for (f in POLICY_FAMILY_NAMES.indices) {
            val family = POLICY_FAMILY_NAMES[f]
            for (i in 0 until POLICY_PER_FAMILY) {
                val baseGroup = "qa20grp-${i % 7}"
                val baseChannel = "qa20ch-${i % 7}"
                val group = when {
                    family == "BOUNDED_SET" -> "NONE"
                    i % 5 == 0 -> "qa20other-${i % 7}"
                    i % 4 == 0 -> " $baseGroup "
                    i % 4 == 1 -> baseGroup.uppercase(java.util.Locale.ROOT)
                    else -> baseGroup
                }
                val channel = if (i % 3 == 0) " $baseChannel " else baseChannel
                val known = i % 2 == 0
                val restrictedGroup = if (i % 5 == 0 && family != "GROUP") "NONE" else baseGroup
                val restrictedChannel = if (i % 3 == 0 && family != "CHANNEL") "NONE" else baseChannel
                val unlocked = i % 4 == 0
                val setSize = when (i % 4) {
                    0 -> MAX_GROUPS
                    1 -> MAX_GROUPS + 1
                    2 -> MAX_GROUPS + 1
                    else -> MAX_GROUPS - 1
                }
                val op = if (i % 4 == 2 || i % 2 == 0) "NORMALIZE" else "RESTRICT"
                val id = "qa20p-" + (f * POLICY_PER_FAMILY + i).toString().padStart(5, '0')
                val p = Policy(
                    id, family, group, channel, known, restrictedGroup, restrictedChannel,
                    unlocked, setSize, op, "",
                )
                out.add(p.copy(expected = oraclePolicy(p)))
            }
        }
        return out
    }

    private fun buildCorrupt(): List<Corrupt> {
        val canonical = buildEvents()[0].render() + "\n"
        val bytes = utf8(canonical)
        val out = ArrayList<Corrupt>(CORRUPT_COUNT)

        val headerVariant = canonical.replaceFirst(EVENT_HEADER, "qa20v0")
        out.add(Corrupt("qa20x-00", hex(utf8(headerVariant)), "HEADER_STRICT"))

        val shortFields = canonical.split('\t').dropLast(1).joinToString("\t")
        out.add(Corrupt("qa20x-01", hex(utf8(shortFields)), "FIELD_COUNT"))

        val badInt = canonical.split('\t').toMutableList().also { it[3] = "9" }.joinToString("\t")
        out.add(Corrupt("qa20x-02", hex(utf8(badInt)), "INT_BOUNDS"))

        val badFamily = canonical.split('\t').toMutableList().also { it[2] = "UNKNOWN_FAMILY" }.joinToString("\t")
        out.add(Corrupt("qa20x-03", hex(utf8(badFamily)), "FAMILY_CODE"))

        out.add(Corrupt("qa20x-04", hex(utf8(canonical + "X".repeat(MAX_LINE))), "LINE_BOUNDS"))

        val nonAscii = bytes.clone()
        val firstDigit = nonAscii.indexOf('0'.toByte())
        if (firstDigit >= 0) nonAscii[firstDigit] = 0xFF.toByte()
        out.add(Corrupt("qa20x-05", hex(nonAscii), "NON_ASCII"))

        val badEntry = canonical.split('\t').toMutableList().also { it[6] = "X" }.joinToString("\t")
        out.add(Corrupt("qa20x-06", hex(utf8(badEntry)), "ENTRY_CODE"))

        val badExpected = canonical.split('\t').toMutableList().also { it[7] = "MAYBE" }.joinToString("\t")
        out.add(Corrupt("qa20x-07", hex(utf8(badExpected)), "EXPECTED_CODE"))
        return out
    }

    private fun buildDimensions(events: List<Event>, policy: List<Policy>, corrupt: List<Corrupt>): String {
        val eventText = events.joinToString("\n") { it.render() } + "\n"
        val policyText = policy.joinToString("\n") { it.render() } + "\n"
        val corruptText = corrupt.joinToString("\n") { it.render() } + "\n"
        return buildString {
            append("seed=$SEED\n")
            append("event_families=$EVENT_FAMILIES\n")
            append("events_per_family=$EVENTS_PER_FAMILY\n")
            append("events=$EVENT_COUNT\n")
            append("policy_families=$POLICY_FAMILIES\n")
            append("policy_per_family=$POLICY_PER_FAMILY\n")
            append("policy_rows=$POLICY_COUNT\n")
            append("corrupt_variants=$CORRUPT_COUNT\n")
            append("max_line=$MAX_LINE\n")
            append("max_groups=$MAX_GROUPS\n")
            append("cycles=$CYCLES\n")
            append("secret_length=$SECRET_LENGTH\n")
            append("events_digest=${fnv(utf8(eventText))}\n")
            append("policy_digest=${fnv(utf8(policyText))}\n")
            append("events_sha256=${sha256(utf8(eventText))}\n")
            append("policy_sha256=${sha256(utf8(policyText))}\n")
            append("corrupt_sha256=${sha256(utf8(corruptText))}\n")
        }
    }

    private fun buildFixture(): Map<String, ByteArray> {
        val events = buildEvents()
        val policy = buildPolicy()
        val corrupt = buildCorrupt()
        val contract = """
            QA-20 scratch fixture for the bounded runtime parental decision slice.
            All identifiers are invented. No feed address, access marker, PIN or recording is stored.
            Event rows replay a failed-entry sequence from a pinned start snapshot.
            Policy rows replay group, channel, recording and bounded-set decisions.
            Corrupt rows carry hex-encoded malformed event lines with a pinned rejection reason.
            The sensitive marker is derived at run time and appears in no file.
        """.trimIndent() + "\n"
        val files = LinkedHashMap<String, ByteArray>()
        files["contract.txt"] = utf8(contract)
        files["dimensions.tsv"] = utf8(buildDimensions(events, policy, corrupt))
        files["events.tsv"] = utf8(events.joinToString("\n") { it.render() } + "\n")
        files["policy.tsv"] = utf8(policy.joinToString("\n") { it.render() } + "\n")
        files["corrupt.hex"] = utf8(corrupt.joinToString("\n") { it.render() } + "\n")
        val manifest = buildString {
            for (name in DATA_FILES.split(',')) {
                append(sha256(files.getValue(name))).append("  ").append(name).append('\n')
            }
        }
        files["sha256.txt"] = utf8(manifest)
        return files
    }

    // ---------------------------------------------------------------------- parsing

    private fun parseManifest(bytes: ByteArray): Map<String, String> {
        val out = LinkedHashMap<String, String>()
        val text = strictUtf8(bytes, "MANIFEST_TEXT")
        for (line in text.lineSequence()) {
            if (line.isEmpty()) continue
            val fields = line.split(Regex("\\s+"))
            if (fields.size != 2 || !SHA_REGEX.matches(fields[0]) || fields[1] !in DATA_FILES.split(',')) {
                throw ParseFail("MANIFEST_FORMAT")
            }
            out[fields[1]] = fields[0]
        }
        if (out.size != DATA_FILES.split(',').size) throw ParseFail("MANIFEST_FORMAT")
        return out
    }

    private fun parseDimensions(bytes: ByteArray): Map<String, String> {
        val out = LinkedHashMap<String, String>()
        for (line in strictUtf8(bytes, "DIMENSION_TEXT").lineSequence()) {
            if (line.isEmpty()) continue
            val at = line.indexOf('=')
            if (at <= 0 || at == line.length - 1) throw ParseFail("DIMENSION_FORMAT")
            out[line.substring(0, at)] = line.substring(at + 1)
        }
        if (out.size < 17) throw ParseFail("DIMENSION_FORMAT")
        return out
    }

    private fun splitStrict(line: String, count: Int, code: String): List<String> {
        val fields = line.split('\t')
        if (fields.size != count) throw ParseFail(code)
        return fields
    }

    private fun parseEventBytes(bytes: ByteArray): Event {
        if (bytes.size > MAX_LINE) throw ParseFail("LINE_BOUNDS")
        val line = strictUtf8(bytes, "NON_ASCII").removeSuffix("\n")
        val f = splitStrict(line, 8, "FIELD_COUNT")
        if (f[0] != EVENT_HEADER) throw ParseFail("HEADER_STRICT")
        if (!ID_REGEX.matches(f[1])) throw ParseFail("ID_FORMAT")
        if (f[2] !in EVENT_FAMILY_NAMES) throw ParseFail("FAMILY_CODE")
        val failures = f[3].toIntOrNull() ?: throw ParseFail("INT_BOUNDS")
        val lock = f[4].toLongOrNull() ?: throw ParseFail("INT_BOUNDS")
        val now = f[5].toLongOrNull() ?: throw ParseFail("INT_BOUNDS")
        if (failures !in 0 until MAX_FAILURES || lock < 0L || now < 0L || lock > Long.MAX_VALUE / 4 || now > Long.MAX_VALUE / 4) {
            throw ParseFail("INT_BOUNDS")
        }
        if (f[6].isEmpty() || f[6].length > 8 || f[6].any { it != 'C' && it != 'W' }) throw ParseFail("ENTRY_CODE")
        if (!OUTCOME_REGEX.matches(f[7])) throw ParseFail("EXPECTED_CODE")
        return Event(f[1], f[2], failures, lock, now, f[6], f[7])
    }

    /** Deliberately relaxed decoder used only as the negative control for strict rejection. */
    private fun laxEventBytes(bytes: ByteArray): Event {
        val text = String(bytes, StandardCharsets.UTF_8).removeSuffix("\n")
        val raw = text.split('\t')
        val f = (0 until 8).map { raw.getOrNull(it) ?: "NONE" }
        return Event(f[1], f[2], f[3].toIntOrNull() ?: 0, f[4].toLongOrNull() ?: 0L,
            f[5].toLongOrNull() ?: 0L, f[6], f[7])
    }

    private fun parseEvents(bytes: ByteArray): List<Event> {
        val out = ArrayList<Event>(EVENT_COUNT)
        for (line in strictUtf8(bytes, "NON_ASCII").lineSequence()) {
            if (line.isEmpty()) continue
            out.add(parseEventBytes(utf8(line)))
        }
        if (out.size != EVENT_COUNT) throw ParseFail("EVENT_COUNT")
        return out
    }

    private fun parsePolicy(bytes: ByteArray): List<Policy> {
        val out = ArrayList<Policy>(POLICY_COUNT)
        for (line in strictUtf8(bytes, "NON_ASCII").lineSequence()) {
            if (line.isEmpty()) continue
            val f = splitStrict(line, 12, "POLICY_FIELD_COUNT")
            if (f[0] != POLICY_HEADER) throw ParseFail("POLICY_HEADER")
            if (!POLICY_ID_REGEX.matches(f[1])) throw ParseFail("POLICY_ID")
            if (f[2] !in POLICY_FAMILY_NAMES) throw ParseFail("POLICY_FAMILY")
            val known = if (f[5] == "TRUE") true else if (f[5] == "FALSE") false else throw ParseFail("POLICY_BOOL")
            val unlocked = if (f[8] == "TRUE") true else if (f[8] == "FALSE") false else throw ParseFail("POLICY_BOOL")
            val size = f[9].toIntOrNull() ?: throw ParseFail("POLICY_INT")
            if (size < 1 || size > MAX_GROUPS + 1) throw ParseFail("POLICY_INT")
            if (f[10] !in setOf("NORMALIZE", "RESTRICT")) throw ParseFail("POLICY_OP")
            if (f[11] !in setOf("TRUE", "FALSE", "REJECT")) throw ParseFail("POLICY_EXPECTED")
            out.add(Policy(f[1], f[2], f[3], f[4], known, f[6], f[7], unlocked, size, f[10], f[11]))
        }
        if (out.size != POLICY_COUNT) throw ParseFail("POLICY_COUNT")
        return out
    }

    private fun parseCorrupt(bytes: ByteArray): List<Corrupt> {
        val out = ArrayList<Corrupt>(CORRUPT_COUNT)
        for (line in strictUtf8(bytes, "NON_ASCII").lineSequence()) {
            if (line.isEmpty()) continue
            val f = splitStrict(line, 4, "CORRUPT_FIELD_COUNT")
            if (f[0] != CORRUPT_HEADER) throw ParseFail("CORRUPT_HEADER")
            if (!CORRUPT_ID_REGEX.matches(f[1])) throw ParseFail("CORRUPT_ID")
            if (!HEX_REGEX.matches(f[2]) || unhex(f[2]) == null) throw ParseFail("CORRUPT_HEX")
            if (f[3] !in CORRUPT_REASONS && f[3] != "ACCEPT") throw ParseFail("CORRUPT_REASON")
            out.add(Corrupt(f[1], f[2], f[3]))
        }
        if (out.size != CORRUPT_COUNT) throw ParseFail("CORRUPT_COUNT")
        return out
    }

    fun leakFound(text: String, secret: String): Boolean {
        val lower = text.lowercase(java.util.Locale.ROOT)
        if (text.contains(secret)) return true
        return SENSITIVE_PATTERNS.any { lower.contains(it) }
    }

    // ----------------------------------------------------------------------- checks

    private class Ctx(
        val fixtureDir: File?,
        val mutant: String?,
        val sink: Sink,
    ) {
        var checks = 0
        var passed = 0
        val failures = ArrayList<String>()

        fun check(id: String, condition: Boolean, code: String) {
            checks++
            if (condition) {
                passed++
                sink.line("CHECK\tPASS\t$id")
            } else {
                failures.add(code)
                sink.line("CHECK\tFAIL\t$id\t$code")
            }
        }
    }

    fun runAll(fixtureDir: File?, sink: Sink, mutant: String? = null): Result {
        val ctx = Ctx(fixtureDir, mutant, sink)
        val secret = deriveSecret()
        val generated = buildFixture()
        val threadStart = Thread.getAllStackTraces().keys.count { it.isAlive }

        if (fixtureDir == null) {
            ctx.check("mirror-generation", generated.size == ALL_FILES.split(',').size, "GENERATION")
            val events = buildEvents()
            val policy = buildPolicy()
            val corrupt = buildCorrupt()
            ctx.check("mirror-counts", events.size == EVENT_COUNT && policy.size == POLICY_COUNT &&
                corrupt.size == CORRUPT_COUNT, "MIRROR_COUNT")
            ctx.check("mirror-outcomes", events.all { productEvent(it) == it.expected } &&
                policy.all { productPolicy(it) == it.expected }, "MIRROR_OUTCOME")
            finish(ctx, secret, threadStart, "", "")
            return result(ctx, sink)
        }

        val onDisk = LinkedHashMap<String, ByteArray>()
        for (name in ALL_FILES.split(',')) {
            val file = File(fixtureDir, name)
            onDisk[name] = if (file.isFile) file.readBytes() else ByteArray(0)
        }

        if (mutant == null) {
            for (name in ALL_FILES.split(',')) {
                ctx.check("byte-identity-$name", onDisk.getValue(name).contentEquals(generated.getValue(name)), "BYTE_IDENTITY")
            }
            val total = onDisk.values.sumOf { it.size.toLong() }
            ctx.check("fixture-bounds", total <= MAX_FIXTURE_BYTES, "FIXTURE_BOUNDS")
            ctx.check("events-sha-pin", sha256(generated.getValue("events.tsv")) == PINNED_EVENTS_SHA, "SHA256_PIN")
            ctx.check("policy-sha-pin", sha256(generated.getValue("policy.tsv")) == PINNED_POLICY_SHA, "SHA256_PIN")
            ctx.check("corrupt-sha-pin", sha256(generated.getValue("corrupt.hex")) == PINNED_CORRUPT_SHA, "SHA256_PIN")
        }

        val manifest = try {
            parseManifest(onDisk.getValue("sha256.txt"))
        } catch (e: ParseFail) {
            sink.line("PARSE\tFAIL\tmanifest\t${e.code}")
            ctx.check("manifest-format", false, e.code)
            emptyMap()
        }
        var manifestOk = manifest.size == DATA_FILES.split(',').size
        for (name in DATA_FILES.split(',')) {
            if (manifest[name] != sha256(onDisk.getValue(name))) manifestOk = false
        }
        ctx.check("manifest-consistency", manifestOk, "MANIFEST_MISMATCH")

        val dims = try {
            parseDimensions(onDisk.getValue("dimensions.tsv"))
        } catch (e: ParseFail) {
            sink.line("PARSE\tFAIL\tdimensions\t${e.code}")
            ctx.check("dimensions", false, e.code)
            emptyMap()
        }
        if (dims.isNotEmpty()) {
            val structural = dims["seed"] == SEED.toString() &&
                dims["event_families"] == EVENT_FAMILIES.toString() &&
                dims["events"] == EVENT_COUNT.toString() &&
                dims["policy_rows"] == POLICY_COUNT.toString() &&
                dims["corrupt_variants"] == CORRUPT_COUNT.toString() &&
                dims["max_line"] == MAX_LINE.toString() &&
                dims["max_groups"] == MAX_GROUPS.toString() &&
                dims["cycles"] == CYCLES.toString() &&
                dims["secret_length"] == SECRET_LENGTH.toString()
            ctx.check("dimensions", structural, "DIMENSIONS")
            if (mutant == null) {
                ctx.check("events-digest-pin", dims["events_digest"] == PINNED_EVENTS_DIGEST, "DIGEST_PIN")
                ctx.check("policy-digest-pin", dims["policy_digest"] == PINNED_POLICY_DIGEST, "DIGEST_PIN")
                ctx.check("dimension-events-sha", dims["events_sha256"] == sha256(onDisk.getValue("events.tsv")), "SHA256_PIN")
                ctx.check("dimension-policy-sha", dims["policy_sha256"] == sha256(onDisk.getValue("policy.tsv")), "SHA256_PIN")
                ctx.check("dimension-corrupt-sha", dims["corrupt_sha256"] == sha256(onDisk.getValue("corrupt.hex")), "SHA256_PIN")
            }
        }

        val events = try {
            parseEvents(onDisk.getValue("events.tsv"))
        } catch (e: ParseFail) {
            sink.line("PARSE\tFAIL\tevents\t${e.code}")
            ctx.check("strict-events", false, e.code)
            emptyList()
        }
        val policy = try {
            parsePolicy(onDisk.getValue("policy.tsv"))
        } catch (e: ParseFail) {
            sink.line("PARSE\tFAIL\tpolicy\t${e.code}")
            ctx.check("strict-policy", false, e.code)
            emptyList()
        }
        val corrupt = try {
            parseCorrupt(onDisk.getValue("corrupt.hex"))
        } catch (e: ParseFail) {
            sink.line("PARSE\tFAIL\tcorrupt\t${e.code}")
            ctx.check("strict-corrupt", false, e.code)
            emptyList()
        }

        var eventMismatch = 0
        var policyMismatch = 0
        var peakThreads = threadStart
        if (events.isNotEmpty() && policy.isNotEmpty()) {
            val worker = Thread({
                peakThreads = Thread.getAllStackTraces().keys.count { it.isAlive }
                repeat(CYCLES) {
                    for (e in events) {
                        val actual = productEvent(e)
                        if (actual != e.expected) {
                            eventMismatch++
                            if (it == 0) sink.line("CASE\tFAIL\t${e.id}\tfamily=${e.family}\texpected=${e.expected}\tactual=$actual")
                        }
                    }
                    for (p in policy) {
                        val actual = productPolicy(p)
                        if (actual != p.expected) {
                            policyMismatch++
                            if (it == 0) sink.line("CASE\tFAIL\t${p.id}\tfamily=${p.family}\texpected=${p.expected}\tactual=$actual")
                        }
                    }
                }
            }, "qa20-worker")
            worker.start()
            worker.join(60_000L)
            ctx.check("worker-joined", !worker.isAlive, "WORKER_TIMEOUT")
        }

        var corruptRejected = 0
        var laxAccepted = 0
        for (c in corrupt) {
            val bytes = unhex(c.hex) ?: continue
            val strict = try {
                parseEventBytes(bytes)
                "ACCEPT"
            } catch (e: ParseFail) {
                e.code
            }
            if (strict == c.reason) corruptRejected++
            try {
                laxEventBytes(bytes)
                laxAccepted++
            } catch (_: Exception) {
                // The control must prove that the relaxed path accepts the payload.
            }
        }
        ctx.check("corrupt-fail-closed", corrupt.isNotEmpty() && corruptRejected == corrupt.size, "CORRUPT_REJECT")
        ctx.check("lax-control-accepts", corrupt.isNotEmpty() && laxAccepted == corrupt.size, "LAX_CONTROL")
        ctx.check("event-outcomes", events.isNotEmpty() && eventMismatch == 0, "OUTCOME_MISMATCH")
        ctx.check("policy-outcomes", policy.isNotEmpty() && policyMismatch == 0, "OUTCOME_MISMATCH")

        val fixtureText = onDisk.values.joinToString("\n") { String(it, StandardCharsets.UTF_8) }
        finish(ctx, secret, threadStart, fixtureText, "")
        sink.line("METRIC\tevent_mismatch=$eventMismatch\tpolicy_mismatch=$policyMismatch\tcorrupt_rejected=$corruptRejected\tpeak_threads=$peakThreads")
        return result(ctx, sink)
    }

    private fun finish(ctx: Ctx, secret: String, threadStart: Int, fixtureText: String, unused: String) {
        System.gc()
        try { Thread.sleep(40L) } catch (_: InterruptedException) { Thread.currentThread().interrupt() }
        val used = Runtime.getRuntime().totalMemory() - Runtime.getRuntime().freeMemory()
        val threads = Thread.getAllStackTraces().keys.count { it.isAlive }
        ctx.sink.line("METRIC\theap_used=$used\theap_limit=$HEAP_LIMIT_BYTES\tthreads=$threads\tthread_start=$threadStart")
        ctx.check("heap-bound", used < HEAP_LIMIT_BYTES, "HEAP_BOUND")
        ctx.check("thread-drift", threads == threadStart, "THREAD_DRIFT")
        ctx.check("no-qa-threads", Thread.getAllStackTraces().keys.none { it.name.startsWith("qa20-") }, "THREAD_LEAK")
        val report = StringBuilder()
        for (code in ctx.failures) report.append("FAIL\t").append(code).append('\n')
        if (ctx.mutant == "leak") report.append(secret).append('\n')
        ctx.check("privacy-scan", !leakFound(report.toString(), secret) &&
            !leakFound(fixtureText, secret), "PRIVACY_SCAN")
    }

    private fun result(ctx: Ctx, sink: Sink): Result {
        val first = ctx.failures.firstOrNull()
        sink.line("FIRST\t${first ?: "NONE"}")
        sink.line("SUMMARY\tchecks=${ctx.checks}\tpass=${ctx.passed}\tfail=${ctx.failures.size}")
        return Result(ctx.checks, ctx.passed, ctx.failures.size, first)
    }

    @JvmStatic
    fun main(args: Array<String>) {
        if (args.isEmpty()) {
            println("usage: Qa20Contract generate <dir> | verify <dir> | verify-mutant <dir> <name> | jvm-mirror")
            exitProcess(2)
        }
        val sink = Sink { println(it) }
        when (args[0]) {
            "generate" -> {
                if (args.size != 2) exitProcess(2)
                val dir = File(args[1])
                dir.mkdirs()
                val fixture = buildFixture()
                for ((name, bytes) in fixture) File(dir, name).writeBytes(bytes)
                File(dir, ".gitattributes").writeBytes(utf8("* -text\n.gitattributes -text\n"))
                println("GENERATE\tfiles=${fixture.size}\tevents=$EVENT_COUNT\tpolicy=$POLICY_COUNT\tcorrupt=$CORRUPT_COUNT" +
                    "\tbytes=${fixture.values.sumOf { it.size }}\tevents_sha256=${sha256(fixture.getValue("events.tsv"))}" +
                    "\tpolicy_sha256=${sha256(fixture.getValue("policy.tsv"))}\tcorrupt_sha256=${sha256(fixture.getValue("corrupt.hex"))}")
            }
            "verify" -> {
                if (args.size != 2) exitProcess(2)
                val result = runAll(File(args[1]), sink, null)
                exitProcess(if (result.ok) 0 else 1)
            }
            "verify-mutant" -> {
                if (args.size != 3) exitProcess(2)
                val result = runAll(File(args[1]), sink, args[2])
                exitProcess(if (result.ok) 0 else 1)
            }
            "jvm-mirror" -> {
                val result = runAll(null, sink, null)
                exitProcess(if (result.ok) 0 else 1)
            }
            else -> exitProcess(2)
        }
    }
}
